import { APPLIER_SPECS } from "../../lib/game-config-appliers";
import type { GameConfigApplier } from "./types";
import { terrariaApplier } from "./terraria";

/**
 * THE applier registry. To add a family: write worker/game-config-appliers/<family>.ts
 * (+ lib/game-applier-specs/<family>.ts), then add ONE line to `register` below and
 * ONE line to APPLIER_SPECS in lib/game-config-appliers.ts. If the two disagree the
 * worker refuses to boot (and test/game-config-appliers.test.ts fails) — see `assertConsistent`.
 * worker/game-config.ts `applyRealConfig` dispatches here for every family it has no
 * inline applier for.
 */
const REGISTRY = new Map<string, GameConfigApplier>();
function register(a: GameConfigApplier) {
  REGISTRY.set(a.spec.family, a);
}

register(terrariaApplier);

/** The registered spec must be the exact object the UI derives from. */
export function assertConsistent(): void {
  for (const [family, a] of REGISTRY) {
    if (APPLIER_SPECS[family] !== a.spec) throw new Error(`game config applier "${family}": its spec is not the one listed in lib/game-config-appliers.ts APPLIER_SPECS`);
  }
  for (const family of Object.keys(APPLIER_SPECS)) {
    if (!REGISTRY.has(family)) throw new Error(`game config applier "${family}" is in APPLIER_SPECS but not registered in worker/game-config-appliers/index.ts`);
  }
}
assertConsistent();

export function getApplier(family: string): GameConfigApplier | null {
  return REGISTRY.get(family) ?? null;
}
export function registeredFamilies(): string[] {
  return [...REGISTRY.keys()];
}
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";

/**
 * The runner every applier goes through. It owns the boring, easy-to-get-wrong
 * parts so an applier only contains its own mechanism:
 *   - which fields are in play (handled ∩ changed) and the "saved but not applied" note for the rest
 *   - idempotent no-op when none of the changed fields belong to the applier
 *   - secret redaction of every note (values of spec fields flagged `secret`, plus any
 *     extra strings an applier registers)
 *   - never throws: an exception becomes an honest failed outcome
 */
export type RunBase = Omit<ApplierContext, "touched" | "family"> & { family?: string };

export function redactor(secrets: string[]): (s: string) => string {
  const list = secrets.filter((s) => s.length >= 3);
  return (s) => list.reduce((acc, x) => acc.split(x).join("***"), s);
}

export function secretValues(applier: GameConfigApplier, values: Record<string, unknown>): string[] {
  return Object.entries(applier.spec.fields)
    .filter(([, f]) => f.secret)
    .map(([k]) => String(values[k] ?? ""))
    .filter((v) => v.length > 0);
}

export async function runApplier(applier: GameConfigApplier, base: RunBase): Promise<ApplyOutcome> {
  const { spec } = applier;
  const handled = Object.keys(spec.fields);
  const changed = base.changed?.filter((k) => !k.startsWith("_") && k !== "variant");
  const touched = changed ? handled.filter((k) => changed.includes(k)) : handled;
  const redact = redactor(secretValues(applier, base.values));

  const unhandled = changed ? changed.filter((k) => !(k in spec.fields)) : [];
  const tail = unhandled.length
    ? [`Saved but not applied to the running game: ${unhandled.join(", ")}. We can't push ${unhandled.length === 1 ? "that setting" : "those settings"} to the server yet.`]
    : [];

  if (touched.length === 0) {
    return { ok: true, applied: [], notes: ["Nothing in this change needs to be applied to the running server.", ...tail] };
  }
  try {
    const out = await applier.apply({ ...base, family: base.family ?? spec.family, touched });
    return { ...out, applied: out.applied.map(redact), notes: [...out.notes.map(redact), ...tail] };
  } catch (e) {
    return { ok: false, applied: [], notes: [redact(`Apply failed: ${(e as Error).message}`.slice(0, 300)), ...tail] };
  }
}
import type { GameConfigApplierSpec } from "../../lib/game-config-appliers";

/**
 * The applier contract. Read docs/DOCUMENTATION.md "Game config appliers" first.
 *
 * An applier is `{ spec, apply }`. `spec` (lib/game-config-appliers.ts) declares
 * which schema fields it handles and how each takes effect; `apply` does the work
 * through `ctx.guest` (never ssh2 directly), so every applier is unit-testable
 * with an in-memory fake guest.
 */

export type Values = Record<string, string | number | boolean>;

export type ExecResult = { code: number; stdout: string; stderr: string };

/** The game server VM as an applier sees it. The framework builds this over SSH/SFTP. */
export interface Guest {
  exec(cmd: string, timeoutMs?: number): Promise<ExecResult>;
  /** null = the file does not exist. */
  readFile(path: string): Promise<string | null>;
  writeFile(path: string, content: string): Promise<void>;
}

/** What an applier returns. `notes`/`applied` are customer-facing and already redacted by the runner. */
export type ApplyOutcome = {
  ok: boolean;
  /** Sentences saying what really changed on the running server. */
  applied: string[];
  /** Everything else the customer should know (not applied, needs restart, kept old world, ...). */
  notes: string[];
  /** True when the apply itself restarted the game (lets the job layer skip a second restart). */
  restarted?: boolean;
  /**
   * True when EVERYTHING applied took effect in the running game with no restart
   * (rcon / live command). The job layer then never tells the customer "restart to apply".
   */
  live?: boolean;
};

export interface ApplierContext {
  family: string;
  server: { id: string; hostname?: string };
  /** Validated, fully populated settings for the family. */
  values: Values;
  /**
   * Schema keys the customer changed in THIS save (+ "variant"). undefined = unknown
   * (auto-queued at provision): treat every handled field as possibly changed, and
   * never do anything destructive-looking (e.g. switching worlds) on that basis.
   */
  changed: string[] | undefined;
  /** The handled fields this run should consider (handled ∩ changed, or all handled when `changed` is unknown). */
  touched: string[];
  guest: Guest;
  /** systemd unit supervising the game container (resolveGameUnit), or null on an older guest. */
  unit: string | null;
  /** Waits for the game port, using the family's window from lib/game-power-start.ts. null = no port known. */
  waitPort(): Promise<{ ok: boolean } | null>;
  /** True when the customer chose "Apply & restart". */
  restartRequested: boolean;
}

export interface GameConfigApplier {
  spec: GameConfigApplierSpec;
