/**
 * Terraria (ryshe/terraria = TShock) applier — mixed strategy. Mechanisms and
 * the reasons for them are documented in lib/game-applier-specs/terraria.ts.
 *
 *  1. TShock keys   -> config-file strategy on /opt/terraria/config.json ("Settings" wrapper),
 *                      verified by reading each key back. Takes effect on restart.
 *  2. World fields  -> env-recreate strategy: a new size/name/seed/difficulty gets its own world
 *                      file (WORLD_FILENAME + launch args); the old world file is never touched.
 *                      Only runs when the customer changed one of these fields in this save.
 *  If step 2 fails, step 1 is rolled back too, so a failure always means "nothing changed".
 */

const ENV_FILE = "/root/terraria.env";

function validateConfigJson(content: string): string | null {
  let doc: unknown;
  try {
    doc = JSON.parse(content);
  } catch {
    return "The result is not valid JSON.";
  }
  if (!doc || typeof doc !== "object" || Array.isArray(doc)) return "The result is not a JSON object.";
  return null;
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const cfgFields = ctx.touched.filter((k) => (TERRARIA_CONFIG_FIELDS as readonly string[]).includes(k));
  const worldTouched = ctx.changed !== undefined && ctx.touched.some((k) => (TERRARIA_WORLD_FIELDS as readonly string[]).includes(k));
  const applied: string[] = [];
  const notes: string[] = [];
  let restore: (() => Promise<void>) | null = null;
  let commit: (() => Promise<void>) | null = null;

  // ---- 1. TShock config.json ------------------------------------------------
  if (cfgFields.length) {
    const want = terrariaTshockSettings(values, cfgFields);
    const res = await patchRemoteFile(guest, {
      path: TERRARIA_CONFIG_JSON,
      patch: (old) => patchJson(old, Object.entries(want).map(([k, v]) => ({ path: [k], value: v })), { wrapper: "Settings" }),
      validate: validateConfigJson,
    });
    if (res.status === "invalid" || res.status === "failed") return { ok: false, applied: [], notes: [res.reason, "Nothing was changed on your server."] };
    if (res.status === "missing") {
      notes.push("TShock hasn't created its config file yet (the server has never fully started), so these settings were saved but not applied: " + cfgFields.join(", ") + ". Start the server once, then save again.");
    } else if (res.status === "unchanged") {
      notes.push(`TShock's config already matched (${cfgFields.join(", ")}) — nothing to change there.`);
    } else {
      restore = res.restore;
      commit = res.commit;
      const back = await guest.readFile(TERRARIA_CONFIG_JSON);
      const actual: Record<string, unknown> = {};
      for (const k of Object.keys(want)) actual[k] = back === null ? undefined : readJson(back, [k], { wrapper: "Settings" });
      const rb = verifyReadback(want, actual);
      if (!rb.ok) {
        await res.restore();
        return { ok: false, applied: [], notes: [`Verification failed for ${rb.mismatched.join(", ")}; TShock's previous config was restored. Nothing was changed on your server.`] };
      }
      applied.push(`Updated TShock's config (${cfgFields.join(", ")}).`);
      if (Number(values["max-players"]) > TERRARIA_MAX_SLOTS && cfgFields.includes("max-players")) {
        notes.push(`TShock allows at most ${TERRARIA_MAX_SLOTS} players, so Max Players was set to ${TERRARIA_MAX_SLOTS}.`);
      }
    }
  }

  // ---- 2. New world (only when the customer changed a world field) ------------
  let restarted = false;
  if (worldTouched) {
    const spec = terrariaWorldSpec(values);
    const file = terrariaWorldFile(spec);
    const existed = (await guest.exec(`test -f ${shq(`${TERRARIA_WORLD_DIR}/${file}`)}`)).code === 0;
    const r = await recreateWithEnv(guest, {
      container: TERRARIA_CONTAINER,
      unit: ctx.unit,
      env: { WORLD_FILENAME: file },
      cmd: (old) => terrariaCmdForWorld(old, spec),
      envFile: ENV_FILE,
      waitPort: ctx.waitPort,
    });
    if (r.status === "failed") {
      if (restore) await restore().catch(() => undefined);
      return { ok: false, applied: [], notes: [r.note, ...(restore ? ["Your TShock settings were put back as well, so nothing was changed."] : [])] };
    }
    if (r.status === "recreated") {
      restarted = r.wasActive;
      applied.push(
        existed
          ? `Switched to your existing world "${file}".`
          : `Created a new world (${file}) and switched to it. Your previous world is still on the server and was not deleted.`,
      );
      notes.push(...r.notes);
      if (r.wasActive) notes.push("Your server restarted briefly to apply this — connected players were disconnected and can rejoin now.");
    } else if (!applied.length) {
      notes.push("This server is already running that world — nothing to change.");
    }
  }

  if (commit) await commit().catch(() => undefined);
  return { ok: true, applied, notes, restarted };
}

export const terrariaApplier: GameConfigApplier = { spec: TERRARIA_SPEC, apply };
import type { Guest } from "../types";
import { shq } from "../types";

/**
 * Config-file strategy: read-modify-write ONE file on the guest with a backup,
 * verification and rollback.
 *
 *   read -> patch(old) -> validate(new) -> (identical? stop: idempotent no-op)
 *   -> backup (path.nxbak) -> write -> read back + validate -> done
 *
 * The patch function is one of kit/json-patch, ini-patch, kv-patch (or your own);
 * it must preserve keys it was not asked to change. Nothing is written when the
 * file is missing or does not parse. The caller decides what happens after
 * (restart etc.) and can still call `restore()` if a LATER step fails.
 */
export type FilePatchResult =
  | { status: "missing" }
  | { status: "invalid"; reason: string }
  | { status: "unchanged" }
  /** Written and verified. `restore` puts the previous content back; `commit` drops the backup. */
  | { status: "changed"; restore(): Promise<void>; commit(): Promise<void> }
  /** The write did not verify; the previous content was restored. */
  | { status: "failed"; reason: string };

export async function patchRemoteFile(
  guest: Guest,
  opts: {
    path: string;
    patch(old: string): string;
    /** Returns an error string if the content is not acceptable (checked before AND after writing). */
    validate?(content: string): string | null;
  },
): Promise<FilePatchResult> {
  const { path } = opts;
  const old = await guest.readFile(path);
  if (old === null) return { status: "missing" };

  let next: string;
  try {
    next = opts.patch(old);
  } catch {
    // Deliberately not echoing the parser's message: it can quote file content.
    return { status: "invalid", reason: `${path} could not be parsed, so it was left untouched.` };
  }
  const bad = opts.validate?.(next);
  if (bad) return { status: "invalid", reason: `${bad} ${path} was left untouched.` };
  if (next === old) return { status: "unchanged" };

  const backup = await guest.exec(`cp -p ${shq(path)} ${shq(path + ".nxbak")}`);
  if (backup.code !== 0) return { status: "failed", reason: `Could not back up ${path} first, so nothing was changed.` };

  const restore = async () => {
    await guest.writeFile(path, old);
    await guest.exec(`rm -f ${shq(path + ".nxbak")}`);
  };

  try {
    await guest.writeFile(path, next);
    const back = await guest.readFile(path);
    const backBad = back === null ? "missing after write" : back !== next ? "differs from what was written" : opts.validate?.(back);
    if (backBad) {
      await restore();
      return { status: "failed", reason: `${path} did not verify after writing (${backBad}); the previous version was restored.` };
    }
  } catch (e) {
    await restore().catch(() => undefined);
    return { status: "failed", reason: `Writing ${path} failed (${(e as Error).message.slice(0, 120)}); the previous version was restored.` };
  }
  return {
    status: "changed",
    restore,
    commit: async () => void (await guest.exec(`rm -f ${shq(path + ".nxbak")}`)),
  };
}
/**
 * INI / CFG patcher. Preserves comments (`;` and `#`), blank lines, key order,
 * unknown keys/sections and the file's line endings; only the requested keys
 * change. A missing key is appended at the end of its section (a missing
 * section is appended at the end of the file). Keys with no section use `section: ""`.
 */

export type IniEdit = { section?: string; key: string; value: string };

const isComment = (l: string) => /^\s*[;#]/.test(l);
const sectionOf = (l: string) => /^\s*\[([^\]]*)\]\s*$/.exec(l)?.[1] ?? null;

export function patchIni(content: string, edits: IniEdit[], opts: { caseSensitive?: boolean } = {}): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const sep = "=";
  const norm = (s: string) => (opts.caseSensitive === false ? s.toLowerCase() : s);
  const lines = content.length ? content.split(/\r?\n/) : [];
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  const done = new Set<number>();

  edits.forEach((e, idx) => {
    const sec = e.section ?? "";
    let cur = "";
    let secStart = sec === "" ? 0 : -1;
    let lastInSec = -1;
    for (let i = 0; i < lines.length; i++) {
      const s = sectionOf(lines[i]);
      if (s !== null) {
        cur = s;
        if (norm(cur) === norm(sec) && secStart < 0) { secStart = i; lastInSec = i; }
        continue;
      }
      if (norm(cur) !== norm(sec)) continue;
      if (!isComment(lines[i]) && lines[i].trim() !== "") lastInSec = i;
      if (isComment(lines[i])) continue;
      const at = lines[i].indexOf("=");
      if (at < 0) continue;
      if (norm(lines[i].slice(0, at).trim()) === norm(e.key)) {
        lines[i] = `${lines[i].slice(0, at).replace(/\s+$/, "")}${sep}${e.value}`;
        done.add(idx);
        return;
      }
    }
    // not found: append
    if (sec === "") {
      // before the first section header, after the last top-level key
      let at = lines.findIndex((l) => sectionOf(l) !== null);
      if (at < 0) at = lines.length;
      lines.splice(at, 0, `${e.key}${sep}${e.value}`);
    } else if (secStart >= 0) {
      lines.splice((lastInSec < 0 ? secStart : lastInSec) + 1, 0, `${e.key}${sep}${e.value}`);
    } else {
      if (lines.length && lines[lines.length - 1].trim() !== "") lines.push("");
      lines.push(`[${sec}]`, `${e.key}${sep}${e.value}`);
    }
  });
  return lines.join(eol) + eol;
}

/** Read one value; undefined if absent. */
export function readIni(content: string, section: string, key: string, caseSensitive = true): string | undefined {
  const norm = (s: string) => (caseSensitive ? s : s.toLowerCase());
  let cur = "";
  for (const l of content.split(/\r?\n/)) {
    const s = sectionOf(l);
    if (s !== null) { cur = s; continue; }
    if (isComment(l) || norm(cur) !== norm(section)) continue;
    const eq = l.indexOf("=");
    if (eq >= 0 && norm(l.slice(0, eq).trim()) === norm(key)) return l.slice(eq + 1).trim();
  }
  return undefined;
}
/**
 * Compare what we meant to write with what we read back from the guest.
 * Returns KEY NAMES only — never values — so a mismatch report can never leak
 * a password into a note, log or job result.
 */
export function verifyReadback(
  expected: Record<string, unknown>,
  actual: Record<string, unknown>,
): { ok: boolean; mismatched: string[] } {
  const mismatched = Object.keys(expected).filter((k) => String(actual[k] ?? "") !== String(expected[k] ?? ""));
  return { ok: mismatched.length === 0, mismatched };
}

/**
 * Per-game customization schema (MVP).
 *
 * A plain module (NO "use server") so it can be imported from server components,
 * "use server" action files AND the worker daemon alike — it holds no secrets and
 * performs no I/O.
 *
 * It declares, per game family, the available server *variants* (the loader/flavour
 * a player runs — Paper vs Vanilla, Carbon vs Oxide, …) and a versioned list of
 * *settings fields* that drive a dynamic UI. Fields are intentionally limited to
 * the handful of options players actually change, keyed on the game's own real
 * config keys (server.properties, PalWorldSettings.ini, cvars, …) — no invented
 * cvars — so a future real "apply" step can render them 1:1.
 *
 * Exports: `familyFor`, `schemaFor`, `validateConfig` plus the `GAME_CONFIG_SCHEMAS`
 * table and its types.
 */

/** Bump when the field set changes in a way the worker/apply step must notice. */
import { fieldRuleError } from "./game-field-rules";
import { APPLIER_SPECS, applierFieldApply, appliersEnabled, type FieldApply } from "./game-config-appliers";
import { FIVEM_LICENSE_KEY_PATTERN, FIVEM_GAME_BUILDS, FIVEM_LOCALES, FIVEM_KNOWN_ARTIFACTS } from "./fivem";

export const GAME_CONFIG_VERSION = 1;

export type FieldType = "enum" | "bool" | "int" | "string";

/**
 * When a setting takes effect:
 *  - "deploy": needs a server restart / redeploy (world seed, tickrate, …)
 *  - "live":   can be pushed to a running server (motd, pvp, max players, …)
 * MVP treats both the same (simulated apply) but the UI surfaces the distinction.
 */
export type FieldPhase = "deploy" | "live";

export type ConfigField = {
  /** The game's own config key (e.g. "max-players", "ServerPlayerMaxNum"). */
  key: string;
  label: string;
  /** UI grouping heading. */
  group: string;
  type: FieldType;
  default: string | number | boolean;
  /** enum only — {value,label} choices. */
  options?: { value: string; label: string }[];
  /**
   * enum only. When true and `options` is long, the settings UI renders a
   * type-to-filter combobox (components/customer/SearchableSelect.tsx)
   * instead of a plain native `<select>` — a flat dropdown of 100+ entries
   * has no usable way to find one. Leave unset for short option lists
   * (gamemode, difficulty, …), where a native select is simpler and fine.
   */
  searchable?: boolean;
  /** int only — inclusive bounds. */
  min?: number;
  max?: number;
  phase: FieldPhase;
  /** optional one-line helper shown under the field. */
  help?: string;
  /**
   * string fields only. When true, `validateConfig` rejects a blank value —
   * used for values with no sane platform default where the server is
   * genuinely non-functional / unjoinable without a customer-supplied
   * credential (e.g. DST's Klei cluster TOKEN — an online DST cluster
   * refuses to start at all without one). Enforced both at order-creation
   * time (lib/game-order.ts, BEFORE payment) and at settings-save time
   * (lib/actions-game-config.ts), so it gates checkout AND blocks a customer
   * from blanking it back out later. See DST.TOKEN below for the motivating
   * incident (added same-day as the family, 2026-08-31 audit).
   */
  required?: boolean;
  /** string only: minimum length of a non-blank value (enforced by validateConfig + shown inline in the wizard). */
  minLength?: number;
  /** string only: value may not appear inside the value of this other field key (Valheim: password vs world name). */
  notInsideField?: string;
  /** string only: the deploy wizard pre-fills a random value the customer can change. */
  suggest?: "password";
  /**
   * Override the docker `-e KEY=` name that `applyGameConfigEnv`
   * (worker/game-variant.ts) substitutes into, when it differs from `key`.
   *
   * Found live 2026-09-11: Valheim's World Name field is keyed `"world"` (a
   * readable schema key, matches the game's own `-world` flag name) but the
   * lloesche/valheim-server image's actual env var is `WORLD_NAME`.
   * `applyGameConfigEnv` matches literally on `field.key`, so `-e world=`
   * never appeared in the setup script and the customer's chosen world name
   * was silently dropped at provisioning — every Valheim server booted on
   * the catalog's hardcoded default world regardless of what was ordered.
   * Set this whenever a field's readable schema key isn't the literal env
   * var name the image expects.
   */
  envKey?: string;
  /**
   * string fields only. Inclusive length bounds checked in addition to the
   * global 256-char cap (UI uses `maxLength` for the input's own limit).
   */
  maxLength?: number;
  /**
   * string fields only. Regex SOURCE (compiled with the `u` flag, tested
   * against the whole value) the value must match — data, not a function, so
   * the schema stays serialisable into the client settings form.
   */
  pattern?: string;
  /** Shown when `pattern`/length rules reject a value. */
  patternError?: string;
};

/**
 * Per-field string rules (length + pattern), shared by `validateConfig`
 * (server) and the settings form (client) so both say the same thing.
 * Returns an error message or null. Blank values on a non-required field are
 * not rule-checked (blank means "unset").
 */
export function stringFieldError(field: ConfigField, v: string): string | null {
  if (field.type !== "string") return null;
  if (v.trim().length === 0) return null;
  if (field.minLength != null && v.length < field.minLength) {
    return `${field.label} must be at least ${field.minLength} characters.`;
  }
  if (field.maxLength != null && v.length > field.maxLength) {
    return `${field.label} is too long (max ${field.maxLength} characters).`;
  }
  if (field.pattern) {
    let re: RegExp | null = null;
    try {
      re = new RegExp(field.pattern, "u");
    } catch {
      re = null;
    }
    if (re && !re.test(v)) return field.patternError ?? `${field.label} contains characters that are not allowed.`;
  }
  return null;
}

