/** ARK: Survival Evolved — `GAME_MOD_IDS` (comma-separated), confirmed both
 *  against the ARK wiki's `-mods=`/`ActiveMods=` mechanism AND against
 *  hermsi/ark-server's own documented env var (exact name match — this
 *  platform's existing GAME_MOD_IDS settings-schema field, lib/game-config.ts,
 *  was already this image's real env var). Ports/volume match this
 *  platform's fixed ark setupScript (prisma/seed-wave1-games.ts). */
async function applyArkWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    const envMap = await readEnvMap(conn, "ark");
    if (!envMap) return { ok: false, error: `Could not find the "ark" container — is the server fully set up?` };
    envMap.set("GAME_MOD_IDS", ids.join(","));
    await writeContainerEnvFile(conn, sftp, "/root/ark.env", envMap);
    const res = await recreateContainer(conn, {
      family: "ark",
      container: "ark",
      runFlags: "-p 7777:7777/udp -p 7778:7778/udp -p 27015:27015/udp -p 27020:27020/tcp -v /opt/ark:/app --env-file /root/ark.env",
      image: "hermsi/ark-server:latest",
    });
    return res.ok ? { ok: true } : { ok: false, error: res.note };
  });
}

