/**
 * Pure helpers shared by the Unreal-engine family specs (ark, arkasa, conan, soulmask,
 * theisle, dragonwilds): the declarative field -> docker env mapping, the shell-quoting the
 * provisioning bake needs, and the bake itself. No I/O, no node imports (the settings page
 * imports the specs).
 */
export type V = Record<string, string | number | boolean | undefined>;

/** One schema field that reaches the game through ONE docker env var. */
export type EnvFieldMap = {
  /** schema field key */
  field: string;
  /** customer-facing name used in "Updated ..." notes */
  label: string;
  /** the docker env var the image reads */
  env: string;
  /** schema value -> env value. `cur` is the container's current env (for composed vars like EXTRA_FLAGS). */
  value(values: V, cur: ReadonlyMap<string, string>): string;
  /** A blank value would stop the game from starting (or leave it unusable): the applier refuses it. */
  refuseBlank?: boolean;
};

/** A variant (map / mode) that is one env var. `map` returns null for an unknown variant id (nothing is changed). */
export type EnvVariantMap = { env: string; label: string; map(variant: string): string | null };

export const str = (v: V, k: string): string => String(v[k] ?? "").trim();
export const int = (v: V, k: string, dflt: number): string => String(Math.trunc(Number(v[k] ?? dflt)));

/** Set (or add) one `-Flag=value` token inside a space-separated flag string, keeping every other token. */
export function setFlagToken(flags: string, name: string, value: string | null): string {
  const toks = flags.split(/\s+/).filter(Boolean).filter((t) => !t.toLowerCase().startsWith(`${name.toLowerCase()}=`));
  if (value !== null) toks.push(`${name}=${value}`);
  return toks.join(" ");
}

/** Single-quote for a POSIX shell. */
export const sq = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

/** Replace `-e KEY=...` in a docker run script, or add it right after `docker run -d`. Returns the script unchanged if it has no `docker run -d`. */
export function setScriptEnv(script: string, key: string, value: string): string {
  const re = new RegExp(`-e\\s+${key}=(?:'[^']*'|"[^"]*"|\\S*)`);
  if (re.test(script)) return script.replace(re, () => `-e ${key}=${sq(value)}`);
  if (!/docker run\s+(?:-d|--detach)\b/.test(script)) return script;
  return script.replace(/(docker run\s+(?:-d|--detach)\b)/, (m) => `${m} -e ${key}=${sq(value)}`);
}

/** Current value of `-e KEY=...` in a script ("" when absent). */
export function scriptEnv(script: string, key: string): string {
  const m = new RegExp(`-e\\s+${key}=('[^']*'|"[^"]*"|\\S*)`).exec(script);
  return m ? m[1].replace(/^['"]|['"]$/g, "") : "";
}

/** Characters that are safe in a password / token these images pass through a shell or a launch string. */
export const SAFE_SECRET_PATTERN = "^[A-Za-z0-9._@%+=-]*$";
export const SAFE_SECRET_ERROR = "Use letters, numbers and . _ @ % + = - only (no spaces or quotes): this game's server image passes the value through a command line.";
EOF

