import type { GameConfigApplierSpec } from "../game-config-appliers";
import { int, str, type EnvFieldMap, type EnvVariantMap, type V } from "./unreal-shared";

/**
 * ARK: Survival Evolved (hermsi/ark-server, arkmanager) — PURE half. Facts below were read off the
 * image's own Dockerfile / conf.d/arkmanager-user.cfg / entrypoint / README, not guessed:
 *
 *  - MAX_PLAYERS, SERVER_PASSWORD, ADMIN_PASSWORD, GAME_MOD_IDS, SERVER_MAP are env vars. arkmanager turns them
 *    into `ark_*` launch arguments, which ARK gives precedence over the INI. A change = recreate the container
 *    with the new env (the volume /opt/ark:/app is kept). An EMPTY SERVER_PASSWORD disables the password (the
 *    image's own default is a non-empty placeholder, so it is always passed explicitly).
 *  - The rate / difficulty / PvE fields are NOT env vars and are NOT on the arkmanager command line, so they live in
 *    GameUserSettings.ini [ServerSettings] (DifficultyOffset, XPMultiplier, TamingSpeedMultiplier,
 *    HarvestAmountMultiplier, ServerPVE: ARK's own documented keys). ARK writes its in-memory settings back to
 *    that file when it shuts down, so a live edit would be overwritten: the applier stops the game, edits the
 *    file, verifies it, and starts the game again. The file is created by ARK itself on its first start, so
 *    before that these fields are reported as saved-but-not-applied (and the post-provision apply picks them up).
 *  - The map (variant) is SERVER_MAP.
 */
export const ARK_CONTAINER = "ark";
export const ARK_ENV_FILE = "/root/ark.env";
/** Host side of the /opt/ark:/app volume. */
export const ARK_INI_PATH = "/opt/ark/server/ShooterGame/Saved/Config/LinuxServer/GameUserSettings.ini";
export const ARK_INI_SECTION = "ServerSettings";

const INI_NOTE = "Applied by briefly stopping the server and editing GameUserSettings.ini (ARK rewrites that file when it shuts down, so it can't be edited while the game runs). The server restarts afterwards.";

export const ARK_SPEC: GameConfigApplierSpec = {
  family: "ark",
  handlesVariant: true,
  fields: {
    MaxPlayers: { when: "recreate" },
    SERVER_PASSWORD: { when: "recreate", secret: true },
    ADMIN_PASSWORD: { when: "recreate", secret: true, note: "Also the RCON password the player list uses; it can't be blank." },
    GAME_MOD_IDS: { when: "recreate", note: "ARK downloads the mods when it starts, so the restart can take several minutes." },
    DifficultyOffset: { when: "recreate", note: INI_NOTE },
    XPMultiplier: { when: "recreate", note: INI_NOTE },
    TamingSpeedMultiplier: { when: "recreate", note: INI_NOTE },
    HarvestAmountMultiplier: { when: "recreate", note: INI_NOTE },
    ServerPVE: { when: "recreate", note: INI_NOTE },
  },
};

export const ARK_ENV_FIELDS: EnvFieldMap[] = [
  { field: "MaxPlayers", label: "Max Players", env: "MAX_PLAYERS", value: (v) => int(v, "MaxPlayers", 20) },
  { field: "SERVER_PASSWORD", label: "Server Password", env: "SERVER_PASSWORD", value: (v) => str(v, "SERVER_PASSWORD") },
  { field: "ADMIN_PASSWORD", label: "Admin Password", env: "ADMIN_PASSWORD", value: (v) => str(v, "ADMIN_PASSWORD"), refuseBlank: true },
  { field: "GAME_MOD_IDS", label: "Workshop Mod IDs", env: "GAME_MOD_IDS", value: (v) => str(v, "GAME_MOD_IDS").replace(/\s+/g, "") },
];

/** variant id -> SERVER_MAP (the names arkmanager/ARK use). */
const MAPS: Record<string, string> = { theisland: "TheIsland", thecenter: "TheCenter", ragnarok: "Ragnarok", scorched: "ScorchedEarth_P", aberration: "Aberration_P" };
export const ARK_VARIANT: EnvVariantMap = { env: "SERVER_MAP", label: "Map", map: (id) => MAPS[id] ?? null };

/** schema field -> GameUserSettings.ini [ServerSettings] key. */
export const ARK_INI_FIELDS = ["DifficultyOffset", "XPMultiplier", "TamingSpeedMultiplier", "HarvestAmountMultiplier", "ServerPVE"] as const;

export function arkIniValues(values: V, only?: readonly string[]): Record<string, string> {
  const want = (k: string) => !only || only.includes(k);
  const out: Record<string, string> = {};
  for (const k of ["DifficultyOffset", "XPMultiplier", "TamingSpeedMultiplier", "HarvestAmountMultiplier"]) if (want(k)) out[k] = String(values[k] ?? "1.0");
  if (want("ServerPVE")) out.ServerPVE = values.ServerPVE === true ? "True" : "False";
  return out;
}

/** ARK writes numbers like 2.000000 and booleans as True/False; compare the way the game reads them. */
export function arkIniSame(key: string, have: string | undefined, want: string): boolean {
  if (have === undefined) return false;
  if (key === "ServerPVE") return have.trim().toLowerCase() === want.toLowerCase();
  const a = Number(have.trim());
  return Number.isFinite(a) && a === Number(want);
}

/** Bake for a fresh install / reinstall: env only (the INI does not exist before ARK's first start). */
export function applyArkSetup(script: string, values: V, setEnv: (s: string, k: string, v: string) => string, variant: string | null): string {
  let out = script;
  const mods = str(values, "GAME_MOD_IDS").replace(/\s+/g, "");
  if (mods) out = setEnv(out, "GAME_MOD_IDS", mods);
  const map = variant ? ARK_VARIANT.map(variant) : null;
  if (map) out = setEnv(out, "SERVER_MAP", map);
  return out;
}
