import type { GameConfigApplierSpec } from "../game-config-appliers";
import { int, setFlagToken, str, type EnvFieldMap, type EnvVariantMap, type V } from "./unreal-shared";

/**
 * ARK: Survival Ascended (sknnr/ark-ascended-server, Windows server under Proton) — PURE half. Read off the image's
 * README and entrypoint.sh: every setting is a docker env var that entrypoint.sh splices into ONE launch string:
 *   SESSION_NAME -> ?SessionName=, SERVER_PASSWORD -> ?ServerPassword=, SERVER_ADMIN_PASSWORD -> ?ServerAdminPassword=,
 *   MODS -> -mods=, EXTRA_FLAGS -> appended verbatim, SERVER_MAP -> the map token.
 * Max players has no env var: the catalog composes `-WinLiveMaxPlayers=<n>` into EXTRA_FLAGS, so the applier edits that
 * one token and keeps any other flag. The launch string is NOT quoted, so a session name with a space is split into
 * separate arguments by the image and breaks the launch; the schema forbids spaces for that reason.
 * All of it needs a recreate (env is fixed at container creation); the volume is kept.
 */
export const ARKASA_CONTAINER = "arkasa";
export const ARKASA_ENV_FILE = "/root/arkasa.env";

export const ARKASA_SPEC: GameConfigApplierSpec = {
  family: "arkasa",
  handlesVariant: true,
  fields: {
    SessionName: { when: "recreate", note: "No spaces: this server image can't pass them to the game." },
    MaxPlayers: { when: "recreate", note: "Passed to the game as -WinLiveMaxPlayers; other launch flags are kept." },
    ServerPassword: { when: "recreate", secret: true },
    AdminPassword: { when: "recreate", secret: true, note: "Also the RCON password the player list uses; it can't be blank." },
    ModIds: { when: "recreate", note: "CurseForge project IDs; the game downloads them when it starts, so the restart can take several minutes." },
  },
};

export const ARKASA_ENV_FIELDS: EnvFieldMap[] = [
  { field: "SessionName", label: "Session Name", env: "SESSION_NAME", value: (v) => str(v, "SessionName"), refuseBlank: true },
  { field: "MaxPlayers", label: "Max Players", env: "EXTRA_FLAGS", value: (v, cur) => setFlagToken(cur.get("EXTRA_FLAGS") ?? "", "-WinLiveMaxPlayers", int(v, "MaxPlayers", 20)) },
  { field: "ServerPassword", label: "Server Password", env: "SERVER_PASSWORD", value: (v) => str(v, "ServerPassword") },
  { field: "AdminPassword", label: "Admin Password", env: "SERVER_ADMIN_PASSWORD", value: (v) => str(v, "AdminPassword"), refuseBlank: true },
  { field: "ModIds", label: "Mod IDs", env: "MODS", value: (v) => str(v, "ModIds").replace(/\s+/g, "") },
];

const MAPS: Record<string, string> = { theisland: "TheIsland_WP", scorched: "ScorchedEarth_WP", aberration: "Aberration_WP" };
export const ARKASA_VARIANT: EnvVariantMap = { env: "SERVER_MAP", label: "Map", map: (id) => MAPS[id] ?? null };

/** Bake the fields that have no `-e` placeholder in the catalog script (MODS, the max-players flag) and the map. */
export function applyArkasaSetup(script: string, values: V, setEnv: (s: string, k: string, v: string) => string, getEnv: (s: string, k: string) => string, variant: string | null): string {
  let out = script;
