import type { ApplierContext, ApplyOutcome, Guest } from "../types";
import { shq } from "../types";
import { recreateWithEnv } from "./env-recreate";
import type { EnvFieldMap, EnvVariantMap } from "../../../lib/game-applier-specs/unreal-shared";

/**
 * Declarative env-var applier on top of `recreateWithEnv`: for every touched schema field that maps to ONE docker env var
 * (EnvFieldMap), compute the wanted value, compare it with the container's CURRENT env, and recreate the container only
 * for the ones that differ. Also handles a variant that is one env var (map / game mode). Used by the Unreal families
 * (ark, arkasa, conan, soulmask, dragonwilds).
 *
 * Honesty rules baked in: a blank value for a field the image cannot run without (`refuseBlank`) is refused BEFORE anything
 * is touched; notes name fields by label and never carry a value; the recreate itself is the kit's (keeps the old
 * container until the new one is verified, restores it on any failure).
 */
export async function readContainerEnv(guest: Guest, container: string): Promise<Map<string, string> | null> {
  const r = await guest.exec(`docker inspect ${shq(container)} --format '{{json .}}'`);
  if (r.code !== 0) return null;
  try {
    const o = JSON.parse(r.stdout.trim());
    const env = new Map<string, string>();
    for (const e of (o.Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) env.set(e.slice(0, i), e.slice(i + 1));
    }
    return env;
  } catch {
    return null;
  }
}

export type EnvApplyOpts = {
  container: string;
  envFile: string;
  fields: EnvFieldMap[];
  variant?: EnvVariantMap;
  /** schema default variant id, used when the server row has none */
  defaultVariant?: string;
  /** shown in "restarted" notes */
  restartHint?: string;
};

export type EnvApplyResult = ApplyOutcome & { status: "noop" | "recreated" | "failed" | "refused" };

export async function applyEnvFields(ctx: ApplierContext, o: EnvApplyOpts): Promise<EnvApplyResult> {
  const { guest, values } = ctx;
  const cur = await readContainerEnv(guest, o.container);
  if (!cur) {
    // The kit's own self-heal can still find a half-finished earlier run; let it try.
    const r = await recreateWithEnv(guest, { container: o.container, unit: ctx.unit, env: {}, envFile: o.envFile, waitPort: ctx.waitPort });
    return { status: "failed", ok: false, applied: [], notes: [r.status === "failed" ? r.note : `Could not read the "${o.container}" game container, so nothing was changed.`] };
  }

  const inPlay = o.fields.filter((f) => ctx.touched.includes(f.field));
  const blank = inPlay.filter((f) => f.refuseBlank && f.value(values, cur) === "");
  if (blank.length) {
    return { status: "refused", ok: false, applied: [], notes: [`${blank.map((f) => f.label).join(", ")} can't be blank: the game would not run without it. Nothing was changed on your server.`] };
  }

  const want: Record<string, string> = {};
  const labels: string[] = [];
  for (const f of inPlay) {
    const v = f.value(values, cur);
    if ((cur.get(f.env) ?? "") !== v) {
      want[f.env] = v;
      labels.push(f.label);
    }
  }
  // Variant (map / mode): reconciled when the customer changed it, or always when the change set is unknown (post-provision).
  if (o.variant && (ctx.changed === undefined || ctx.changed.includes("variant"))) {
    const id = ctx.variant ?? o.defaultVariant ?? null;
    const target = id ? o.variant.map(id) : null;
    if (target !== null && (cur.get(o.variant.env) ?? "") !== target) {
      want[o.variant.env] = target;
      labels.push(o.variant.label);
    }
  }
  if (!labels.length) return { status: "noop", ok: true, applied: [], notes: ["The running server already matches these settings, nothing to change."] };

  const r = await recreateWithEnv(guest, { container: o.container, unit: ctx.unit, env: want, envFile: o.envFile, waitPort: ctx.waitPort });
  if (r.status === "failed") return { status: "failed", ok: false, applied: [], notes: [r.note] };
  if (r.status === "noop") return { status: "noop", ok: true, applied: [], notes: ["The running server already matches these settings, nothing to change."] };
  const notes = [...r.notes];
  if (r.wasActive) notes.push(`Your server restarted to apply this${o.restartHint ? ` (${o.restartHint})` : ""}. Connected players were disconnected and can rejoin once it is back.`);
  else notes.push("Your server is stopped, so the new settings take effect the next time you start it.");
  return { status: "recreated", ok: true, applied: [`Updated ${labels.join(", ")} on the game server.`], notes, restarted: r.wasActive };
}
EOF
cat > kit/stopped-patch.ts <<'EOF'
import type { Guest } from "../types";
import { shq } from "../types";
import { patchRemoteFile } from "./config-file";
import { patchIni, readIni, type IniEdit } from "./ini-patch";

/**
 * Stopped-edit strategy for games that rewrite their own config file from memory when they shut down (ARK's
 * GameUserSettings.ini): a live edit would simply be overwritten. Read the file; if it already matches, do nothing and never
 * touch the game; otherwise stop the game, re-read (the shutdown itself may have rewritten it), patch + verify + restore-on-failure
 * via patchRemoteFile, and start it again only if it was running. Any failure puts the game back as it was.
 */
export type StoppedPatchOpts = {
  path: string;
  section: string;
  edits: IniEdit[];
  /** Does the current value of this key already equal the wanted one? (numeric / boolean aware) */
  same(key: string, have: string | undefined, want: string): boolean;
  container: string;
  unit: string | null;
  waitPort(): Promise<{ ok: boolean } | null>;
};

export type StoppedPatchResult =
  | { status: "missing" }
  | { status: "unchanged" }
  | { status: "changed"; wasActive: boolean; notes: string[] }
  | { status: "failed"; note: string };

export async function patchIniWhileStopped(guest: Guest, o: StoppedPatchOpts): Promise<StoppedPatchResult> {
  const matches = (c: string) => o.edits.every((e) => o.same(e.key, readIni(c, o.section, e.key, false), e.value));
  const first = await guest.readFile(o.path);
  if (first === null) return { status: "missing" };
  if (matches(first)) return { status: "unchanged" };

  const running = async () => (await guest.exec(`docker inspect -f '{{.State.Running}}' ${shq(o.container)} 2>/dev/null`)).stdout.trim() === "true";
  const wasActive = o.unit ? (await guest.exec(`systemctl is-active ${shq(o.unit)}`)).stdout.trim() === "active" : await running();
  const start = o.unit ? `systemctl start ${shq(o.unit)}` : `docker start ${shq(o.container)}`;
  const stop = o.unit ? `systemctl stop ${shq(o.unit)}` : `docker stop ${shq(o.container)}`;
  const startAgain = async () => {
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
  };

  if (wasActive) {
    const st = await guest.exec(stop, 180_000);
    if (st.code !== 0 || (await running())) {
      await startAgain();
      return { status: "failed", note: "Could not stop the game cleanly, so nothing was changed." };
    }
  }

  const res = await patchRemoteFile(guest, {
    path: o.path,
    patch: (old) => patchIni(old, o.edits, { caseSensitive: false }),
    validate: (c) => (c.trim() === "" ? "The result is empty." : null),
  });
  if (res.status === "invalid" || res.status === "failed") {
    await startAgain();
    return { status: "failed", note: `${res.reason} The server was started again unchanged.` };
  }
  if (res.status === "missing") {
    await startAgain();
    return { status: "missing" };
  }
  if (res.status === "changed") {
    const back = await guest.readFile(o.path);
    if (back === null || !matches(back)) {
      await res.restore();
      await startAgain();
      return { status: "failed", note: "Verification failed after writing the settings file; the previous file was restored and the server started again." };
    }
  }

  const notes: string[] = [];
  if (wasActive) {
    const s = await guest.exec(start, 120_000);
    const port = s.code === 0 ? await o.waitPort() : null;
    if (s.code !== 0 || !(await running())) {
      if (res.status === "changed") await res.restore();
      await guest.exec(start, 120_000).catch(() => undefined);
      return { status: "failed", note: "The game did not start with the new settings; the previous settings file was restored." };
    }
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked; it may still be loading.");
  }
  if (res.status === "changed") await res.commit();
  return { status: "changed", wasActive, notes };
}
EOF

