 * for the ones that differ. Also handles a variant that is one env var (map / game mode). Used by the Unreal families
 * (ark, arkasa, conan, soulmask, dragonwilds).
 *
 * Honesty rules baked in: a blank value for a field the image cannot run without (`refuseBlank`) is refused BEFORE anything
 * is touched; notes name fields by label and never carry a value; the recreate itself is the kit's (keeps the old
 * container until the new one is verified, restores it on any failure).
 */
export async function readContainerEnv(guest: Guest, container: string): Promise<Map<string, string> | null> {
  const r = await guest.exec(`docker inspect ${shq(container)} --format '{{json .}}'`);
  if (r.code !== 0) return null;
  try {
    const o = JSON.parse(r.stdout.trim());
    const env = new Map<string, string>();
    for (const e of (o.Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) env.set(e.slice(0, i), e.slice(i + 1));
    }
    return env;
  } catch {
    return null;
  }
}

export type EnvApplyOpts = {
  container: string;
  envFile: string;
  fields: EnvFieldMap[];
  variant?: EnvVariantMap;
  /** schema default variant id, used when the server row has none */
  defaultVariant?: string;
  /** shown in "restarted" notes */
  restartHint?: string;
};

export type EnvApplyResult = ApplyOutcome & { status: "noop" | "recreated" | "failed" | "refused" };

export async function applyEnvFields(ctx: ApplierContext, o: EnvApplyOpts): Promise<EnvApplyResult> {
  const { guest, values } = ctx;
  const cur = await readContainerEnv(guest, o.container);
  if (!cur) {
    // The kit's own self-heal can still find a half-finished earlier run; let it try.
    const r = await recreateWithEnv(guest, { container: o.container, unit: ctx.unit, env: {}, envFile: o.envFile, waitPort: ctx.waitPort });
    return { status: "failed", ok: false, applied: [], notes: [r.status === "failed" ? r.note : `Could not read the "${o.container}" game container, so nothing was changed.`] };
  }

  const inPlay = o.fields.filter((f) => ctx.touched.includes(f.field));
  const blank = inPlay.filter((f) => f.refuseBlank && f.value(values, cur) === "");
  if (blank.length) {
    return { status: "refused", ok: false, applied: [], notes: [`${blank.map((f) => f.label).join(", ")} can't be blank: the game would not run without it. Nothing was changed on your server.`] };
  }

  const want: Record<string, string> = {};
  const labels: string[] = [];
  for (const f of inPlay) {
    const v = f.value(values, cur);
    if ((cur.get(f.env) ?? "") !== v) {
      want[f.env] = v;
      labels.push(f.label);
    }
  }
  // Variant (map / mode): reconciled when the customer changed it, or always when the change set is unknown (post-provision).
  if (o.variant && (ctx.changed === undefined || ctx.changed.includes("variant"))) {
    const id = ctx.variant ?? o.defaultVariant ?? null;
    const target = id ? o.variant.map(id) : null;
    if (target !== null && (cur.get(o.variant.env) ?? "") !== target) {
      want[o.variant.env] = target;
      labels.push(o.variant.label);
    }
  }
  if (!labels.length) return { status: "noop", ok: true, applied: [], notes: ["The running server already matches these settings, nothing to change."] };

  const r = await recreateWithEnv(guest, { container: o.container, unit: ctx.unit, env: want, envFile: o.envFile, waitPort: ctx.waitPort });
  if (r.status === "failed") return { status: "failed", ok: false, applied: [], notes: [r.note] };
  if (r.status === "noop") return { status: "noop", ok: true, applied: [], notes: ["The running server already matches these settings, nothing to change."] };
  const notes = [...r.notes];
  if (r.wasActive) notes.push(`Your server restarted to apply this${o.restartHint ? ` (${o.restartHint})` : ""}. Connected players were disconnected and can rejoin once it is back.`);
  else notes.push("Your server is stopped, so the new settings take effect the next time you start it.");
  return { status: "recreated", ok: true, applied: [`Updated ${labels.join(", ")} on the game server.`], notes, restarted: r.wasActive };
}
