import type { Guest } from "../types";
import { shq } from "../types";
import { patchRemoteFile } from "./config-file";
import { patchIni, readIni, type IniEdit } from "./ini-patch";

/**
 * Stopped-edit strategy for games that rewrite their own config file from memory when they shut down (ARK's
 * GameUserSettings.ini): a live edit would simply be overwritten. Read the file; if it already matches, do nothing and never
 * touch the game; otherwise stop the game, re-read (the shutdown itself may have rewritten it), patch + verify + restore-on-failure
 * via patchRemoteFile, and start it again only if it was running. Any failure puts the game back as it was.
 */
export type StoppedPatchOpts = {
  path: string;
  section: string;
  edits: IniEdit[];
  /** Does the current value of this key already equal the wanted one? (numeric / boolean aware) */
  same(key: string, have: string | undefined, want: string): boolean;
  container: string;
  unit: string | null;
  waitPort(): Promise<{ ok: boolean } | null>;
};

export type StoppedPatchResult =
  | { status: "missing" }
  | { status: "unchanged" }
  | { status: "changed"; wasActive: boolean; notes: string[] }
  | { status: "failed"; note: string };

export async function patchIniWhileStopped(guest: Guest, o: StoppedPatchOpts): Promise<StoppedPatchResult> {
  const matches = (c: string) => o.edits.every((e) => o.same(e.key, readIni(c, o.section, e.key, false), e.value));
  const first = await guest.readFile(o.path);
  if (first === null) return { status: "missing" };
  if (matches(first)) return { status: "unchanged" };

  const running = async () => (await guest.exec(`docker inspect -f '{{.State.Running}}' ${shq(o.container)} 2>/dev/null`)).stdout.trim() === "true";
  const wasActive = o.unit ? (await guest.exec(`systemctl is-active ${shq(o.unit)}`)).stdout.trim() === "active" : await running();
  const start = o.unit ? `systemctl start ${shq(o.unit)}` : `docker start ${shq(o.container)}`;
  const stop = o.unit ? `systemctl stop ${shq(o.unit)}` : `docker stop ${shq(o.container)}`;
  const startAgain = async () => {
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
  };

  if (wasActive) {
    const st = await guest.exec(stop, 180_000);
    if (st.code !== 0 || (await running())) {
      await startAgain();
      return { status: "failed", note: "Could not stop the game cleanly, so nothing was changed." };
    }
  }

  const res = await patchRemoteFile(guest, {
    path: o.path,
    patch: (old) => patchIni(old, o.edits, { caseSensitive: false }),
    validate: (c) => (c.trim() === "" ? "The result is empty." : null),
  });
  if (res.status === "invalid" || res.status === "failed") {
    await startAgain();
    return { status: "failed", note: `${res.reason} The server was started again unchanged.` };
  }
  if (res.status === "missing") {
    await startAgain();
    return { status: "missing" };
  }
  if (res.status === "changed") {
    const back = await guest.readFile(o.path);
    if (back === null || !matches(back)) {
      await res.restore();
      await startAgain();
      return { status: "failed", note: "Verification failed after writing the settings file; the previous file was restored and the server started again." };
    }
  }

  const notes: string[] = [];
  if (wasActive) {
    const s = await guest.exec(start, 120_000);
    const port = s.code === 0 ? await o.waitPort() : null;
    if (s.code !== 0 || !(await running())) {
      if (res.status === "changed") await res.restore();
      await guest.exec(start, 120_000).catch(() => undefined);
      return { status: "failed", note: "The game did not start with the new settings; the previous settings file was restored." };
    }
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked; it may still be loading.");
  }
  if (res.status === "changed") await res.commit();
  return { status: "changed", wasActive, notes };
}
EOF

