import { ARK_CONTAINER, ARK_ENV_FIELDS, ARK_ENV_FILE, ARK_INI_FIELDS, ARK_INI_PATH, ARK_INI_SECTION, ARK_SPEC, ARK_VARIANT, arkIniSame, arkIniValues } from "../../lib/game-applier-specs/ark";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { applyEnvFields } from "./kit/env-fields";
import { patchIniWhileStopped } from "./kit/stopped-patch";

/**
 * ARK: Survival Evolved (hermsi/ark-server) applier. Mechanisms and their sources: lib/game-applier-specs/ark.ts.
 *   1. env fields + map  -> container recreate (volume kept), verified by the kit.
 *   2. INI fields        -> stop, edit GameUserSettings.ini [ServerSettings], verify, start (ARK rewrites the file on shutdown).
 * Step 1 runs first; a failure there stops the run before the game is touched again. Step 2 failing after step 1
 * succeeded is reported as such (ok:false, with what DID apply listed), never as a blanket success.
 */
async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const applied: string[] = [];
  const notes: string[] = [];
  let restarted = false;

  const wantsEnv = ctx.touched.some((k) => ARK_ENV_FIELDS.some((f) => f.field === k)) || ctx.touched.includes("variant") || ctx.changed === undefined;
  if (wantsEnv) {
    const r = await applyEnvFields(ctx, {
      container: ARK_CONTAINER,
      envFile: ARK_ENV_FILE,
      fields: ARK_ENV_FIELDS,
      variant: ARK_VARIANT,
      defaultVariant: "theisland",
      restartHint: "ARK can take a few minutes to load",
    });
    if (!r.ok) return r;
    applied.push(...r.applied);
    notes.push(...r.notes.filter((n) => !/already matches/.test(n)));
    restarted = r.restarted === true;
  }

  const iniFields = ctx.touched.filter((k) => (ARK_INI_FIELDS as readonly string[]).includes(k));
  if (iniFields.length) {
    const want = arkIniValues(ctx.values, iniFields);
    const r = await patchIniWhileStopped(ctx.guest, {
      path: ARK_INI_PATH,
      section: ARK_INI_SECTION,
      edits: Object.entries(want).map(([key, value]) => ({ section: ARK_INI_SECTION, key, value })),
      same: arkIniSame,
      container: ARK_CONTAINER,
      unit: ctx.unit,
      waitPort: ctx.waitPort,
    });
    if (r.status === "failed") {
      return { ok: false, applied, notes: [...(applied.length ? ["The container settings above were applied, but the game rules were not:"] : []), r.note, ...notes] };
    }
    if (r.status === "missing") {
      notes.push(`ARK hasn't created its settings file yet (the server has never fully started), so these were saved but not applied: ${iniFields.join(", ")}. Start the server once, then save again.`);
    } else if (r.status === "changed") {
      applied.push(`Updated the game rules in GameUserSettings.ini (${iniFields.join(", ")}).`);
      notes.push(...r.notes);
      if (r.wasActive) {
        restarted = true;
        notes.push("Your server restarted to apply this; ARK can take a few minutes to load.");
      } else notes.push("Your server is stopped, so the new rules take effect the next time you start it.");
    }
  }

  if (!applied.length && !notes.length) notes.push("The running server already matches these settings, nothing to change.");
  return { ok: true, applied, notes, restarted };
}

export const arkApplier: GameConfigApplier = { spec: ARK_SPEC, apply };
