import type { ApplierContext, GameConfigApplier } from "./types";
import { applyEnvFields } from "./kit/env-fields";

/** Conan Exiles (melle2 image): documented env vars only; see lib/game-applier-specs/conan.ts (the image's server has never been seen running here). */
export const conanApplier: GameConfigApplier = {
  spec: CONAN_SPEC,
