cat > theisle.ts <<'EOF'
import { THEISLE_FIELDS, THEISLE_GAME_INI, THEISLE_INI_DIR, THEISLE_SESSION_SECTION, THEISLE_SPEC, theisleGameIni, theisleIniValues } from "../../lib/game-applier-specs/theisle";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { shq } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { patchIni, readIni } from "./kit/ini-patch";
import { verifyReadback } from "./kit/readback";

/**
 * The Isle: Evrima (ghcr.io/auhrus/theisleevrima) applier. Game.ini under the volume is the only config surface and the server
 * never creates it (lib/game-applier-specs/theisle.ts), so: patch our five keys when the file exists, create it from the image's
 * minimum template when it does not. Game.ini is read at start, so nothing here is live and the applier never restarts.
 */
async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const fields = ctx.touched.filter((k) => (THEISLE_FIELDS as readonly string[]).includes(k));
  const want = theisleIniValues(values, fields);

  const existing = await guest.readFile(THEISLE_GAME_INI);
  if (existing === null) {
    const mk = await guest.exec(`mkdir -p ${shq(THEISLE_INI_DIR)}`);
    if (mk.code !== 0) return { ok: false, applied: [], notes: ["Could not create the settings folder on your server, so nothing was changed."] };
    try {
      await guest.writeFile(THEISLE_GAME_INI, theisleGameIni(values));
    } catch {
      return { ok: false, applied: [], notes: ["Could not write Game.ini on your server, so nothing was changed."] };
    }
    await guest.exec(`chown -R 1000:1000 ${shq("/opt/theisle")}`);
    const back = await guest.readFile(THEISLE_GAME_INI);
    if (back === null || back !== theisleGameIni(values)) {
      await guest.exec(`rm -f ${shq(THEISLE_GAME_INI)}`);
      return { ok: false, applied: [], notes: ["Game.ini did not verify after writing, so it was removed again. Nothing was changed."] };
    }
    return {
      ok: true,
      applied: ["Created Game.ini with your settings (The Isle needs this file and had none)."],
      notes: ["The Isle reads Game.ini when it starts: restart the server to use these settings."],
    };
  }

  const res = await patchRemoteFile(guest, {
    path: THEISLE_GAME_INI,
    patch: (old) => patchIni(old, Object.entries(want).map(([key, value]) => ({ section: THEISLE_SESSION_SECTION, key, value })), { caseSensitive: false }),
    validate: (c) => (c.includes(`[${THEISLE_SESSION_SECTION}]`) ? null : "The result has no TIGameSession section."),
  });
  if (res.status === "invalid" || res.status === "failed") return { ok: false, applied: [], notes: [res.reason, "Nothing was changed on your server."] };
  if (res.status === "missing") return { ok: false, applied: [], notes: ["Game.ini disappeared while applying, so nothing was changed."] };
  if (res.status === "unchanged") return { ok: true, applied: [], notes: ["Game.ini already matched these settings, nothing to change."] };

  const back = (await guest.readFile(THEISLE_GAME_INI)) ?? "";
  const actual: Record<string, unknown> = {};
  for (const k of Object.keys(want)) actual[k] = readIni(back, THEISLE_SESSION_SECTION, k, false);
  const rb = verifyReadback(want, actual);
  if (!rb.ok) {
    await res.restore();
    return { ok: false, applied: [], notes: [`Verification failed for ${rb.mismatched.join(", ")}; the previous Game.ini was restored. Nothing was changed on your server.`] };
  }
  await res.commit();
  return {
    ok: true,
    applied: [`Updated Game.ini (${fields.join(", ")}).`],
    notes: ["The Isle reads Game.ini when it starts: restart the server to use these settings."],
  };
}

export const theisleApplier: GameConfigApplier = { spec: THEISLE_SPEC, apply };
EOF

