import { validateConfig } from "../../lib/game-config";
import { applyArkSetup } from "../../lib/game-applier-specs/ark";
import { applyArkasaSetup } from "../../lib/game-applier-specs/arkasa";
import { applyConanSetup } from "../../lib/game-applier-specs/conan";
import { applyDragonwildsSetup } from "../../lib/game-applier-specs/dragonwilds";
import { applySoulmaskSetup } from "../../lib/game-applier-specs/soulmask";
import { applyTheisleSetup } from "../../lib/game-applier-specs/theisle";
import { scriptEnv, setScriptEnv } from "../../lib/game-applier-specs/unreal-shared";
import { appliersEnabled } from "../../lib/game-config-appliers";

/**
 * Provision / reinstall bake for the Unreal families (ark, arkasa, conan, soulmask, theisle, dragonwilds): what a customer saved
 * at checkout or in Settings must be in the install script, so a fresh server and a "Wipe & reinstall" come up configured (the
 * worker applier only runs on Settings saves). Plain `-e KEY=` env fields are already baked by applyGameConfigEnv (via the
 * schema's `envKey`); this adds what that cannot express: env vars the catalog script has no placeholder for, composed flags,
 * the variant (map / mode) and The Isle's Game.ini. Pure string rewrite; returns the script unchanged for any other family.
 * Called from buildGameSetupScript (worker/game-variant.ts). Honours the NXEON_GAMECFG_APPLIERS=off kill switch.
 */
export function applyUnrealSetupFor(script: string, family: string | null, gameConfig: unknown, variant: string | null | undefined): string {
  if (!family || !appliersEnabled()) return script;
  if (!["ark", "arkasa", "conan", "soulmask", "theisle", "dragonwilds"].includes(family)) return script;
  const v = validateConfig(family, (gameConfig as Record<string, unknown> | null) ?? {});
  if (!v.ok) return script;
  const vals = v.values;
  const var0 = variant ?? null;
  switch (family) {
    case "ark": return applyArkSetup(script, vals, setScriptEnv, var0);
    case "arkasa": return applyArkasaSetup(script, vals, setScriptEnv, scriptEnv, var0);
    case "conan": return applyConanSetup(script, vals, setScriptEnv, scriptEnv);
    case "soulmask": return applySoulmaskSetup(script, setScriptEnv, var0);
    case "dragonwilds": return applyDragonwildsSetup(script, vals, setScriptEnv);
    case "theisle": return applyTheisleSetup(script, vals);
    default: return script;
  }
}
EOF
