  assert.ok(v.ok, JSON.stringify(v));
  return v.values;
};

/** A fake guest whose game container looks like `family`'s real one (env/cmd come from the catalog setup scripts). */
function guestFor(container: string, env: string[], over: { files?: Record<string, string>; active?: boolean; createFails?: boolean; corruptWrite?: string } = {}) {
  const g = fakeGuest({ container, unit: `${container}.service`, ...over });
  const c = g.containers.get(container)!;
  c.image = `example/${container}:latest`;
  c.env = ["PATH=/usr/bin", "DOTNET=9", ...env];
  c.cmd = [];
  c.binds = [`/opt/${container}:/data`];
  c.ports = { "7777/udp": [{ HostIp: "", HostPort: "7777" }] };
  return g;
}
const envOf = (g: ReturnType<typeof fakeGuest>, name: string) => new Map(g.containers.get(name)!.env.map((e) => [e.slice(0, e.indexOf("=")), e.slice(e.indexOf("=") + 1)] as const));
function run(applier: GameConfigApplier, g: ReturnType<typeof fakeGuest>, values: Vals, changed: string[] | undefined, extra: { variant?: string | null; restartRequested?: boolean } = {}) {
  return runApplier(applier, { server: { id: "s1" }, values, changed, restartRequested: extra.restartRequested ?? false, variant: extra.variant, guest: g.guest, unit: g.unit, waitPort: async () => ({ ok: true }) });
}

