  for (const [family, spec] of Object.entries(specs)) {
    const keys = GAME_CONFIG_SCHEMAS[family].fields.map((f) => f.key);
    for (const k of Object.keys(spec.fields)) assert.ok(keys.includes(k), `${family}.${k}`);
