const ARK_INI = `[ServerSettings]
ActiveMutators=
ServerPVE=False
DifficultyOffset=0.200000
XPMultiplier=1.000000
TamingSpeedMultiplier=1.000000
HarvestAmountMultiplier=1.000000
ShowMapPlayerLocation=True
; keep this comment

[/Script/ShooterGame.ShooterGameUserSettings]
MasterAudioVolume=1.000000

[SessionSettings]
SessionName=Nxeon

[MessageOfTheDay]
Message=Hello
Duration=20
`;
const arkIni = (g: ReturnType<typeof fakeGuest>, key: string) => readIni(g.files.get(ARK_INI_PATH)!, "ServerSettings", key, false);
const ARK_ENVB = ["ADMIN_PASSWORD=x", "SERVER_MAP=TheIsland"];

test("ARK ini: each rate/difficulty/PvE field is written to [ServerSettings] with the game stopped, then started; the rest of the file is intact", async () => {
  const cases: [string, string | number | boolean, string, string][] = [
    ["DifficultyOffset", "1.0", "DifficultyOffset", "1.0"],
    ["XPMultiplier", "5.0", "XPMultiplier", "5.0"],
    ["TamingSpeedMultiplier", "10.0", "TamingSpeedMultiplier", "10.0"],
    ["HarvestAmountMultiplier", "3.0", "HarvestAmountMultiplier", "3.0"],
    ["ServerPVE", true, "ServerPVE", "True"],
  ];
  for (const [field, value, key, expected] of cases) {
    const g = guestFor("ark", ARK_ENVB, { files: { [ARK_INI_PATH]: ARK_INI } });
    const out = await run(arkApplier, g, defaults("ark", { [field]: value }), [field]);
    assert.equal(out.ok, true, `${field}: ${JSON.stringify(out.notes)}`);
    assert.equal(arkIni(g, key), expected, field);
    const txt = g.files.get(ARK_INI_PATH)!;
    assert.ok(txt.includes("; keep this comment") && txt.includes("ShowMapPlayerLocation=True") && txt.includes("SessionName=Nxeon") && txt.includes("[MessageOfTheDay]"), "rest preserved");
    const stop = g.log.findIndex((l) => l.includes("systemctl stop"));
    const wr = g.log.findIndex((l) => l === `write ${ARK_INI_PATH}`);
    const start = g.log.findIndex((l) => l.includes("systemctl start"));
    assert.ok(stop >= 0 && wr > stop && start > wr, `${field}: stop -> write -> start (got ${stop},${wr},${start})`);
    assert.equal(g.containers.get("ark")!.running, true);
    assert.equal(g.st.created, 0, "ini fields never recreate the container");
    assert.ok(!g.files.has(ARK_INI_PATH + ".nxbak"));
  }
});

test("ARK ini: values that already match (2.000000 vs 2.0, True vs true) never stop the game", async () => {
  const ini = ARK_INI.replace("XPMultiplier=1.000000", "XPMultiplier=2.000000").replace("ServerPVE=False", "ServerPVE=True");
  const g = guestFor("ark", ARK_ENVB, { files: { [ARK_INI_PATH]: ini } });
  const out = await run(arkApplier, g, defaults("ark", { XPMultiplier: "2.0", ServerPVE: true }), ["XPMultiplier", "ServerPVE"]);
  assert.equal(out.ok, true);
  assert.ok(!g.log.some((l) => l.includes("systemctl stop")));
  assert.equal(g.files.get(ARK_INI_PATH), ini);
  assert.ok(out.notes.join(" ").includes("already matches"));
});

test("ARK ini: a stopped server is edited and left stopped; a missing file is saved-only with an honest note", async () => {
