/** A fake guest whose game container looks like `family`'s real one (env/cmd come from the catalog setup scripts). */
function guestFor(container: string, env: string[], over: { files?: Record<string, string>; active?: boolean; createFails?: boolean; corruptWrite?: string } = {}) {
